#X3D V4.1 utf8 X_ITE V16.5.0

PROFILE Interchange

COMPONENT EnvironmentalSensor : 3
COMPONENT PointingDeviceSensor : 1
COMPONENT Scripting : 1
COMPONENT Sound : 3
COMPONENT Text : 2

WorldInfo {
  title "x10 sensors"
}

NavigationInfo {
  type "NONE"
}

Viewpoint {
  description "front"
  position 0 0 12
}

Transform {
  translation -3 1.5 0
  children [
    DEF TOUCH_TS TouchSensor {
      description "touch me"
    }
    Shape {
      appearance Appearance {
        material Material {
          diffuseColor 0.8 0.2 0.2
        }
      }
      geometry Box {
        size 1.6 1.6 1.6
      }
    }
  ]
}

DEF MARKER Transform {
  translation 0.2001951 -0.09556687 0.8000002
  children Shape {
    appearance Appearance {
      material DEF MARKER_MAT Material {
        diffuseColor 1 1 1
      }
    }
    geometry Sphere {
      radius 0.15
    }
  }
}

DEF TOUCH_CLOCK TimeSensor {
  cycleInterval 2
  startTime 946684800.1
}

DEF PLANE_BOX Transform {
  children [
    DEF PLANE_PS PlaneSensor {
      minPosition -2 -2
      maxPosition 2 2
    }
    Shape {
      appearance Appearance {
        material Material {
          diffuseColor 0.2 0.8 0.2
        }
      }
      geometry Box {
        size 1.4 1.4 0.6
      }
    }
  ]
}

DEF CYL_BOX Transform {
  translation 3 1.5 0
  children [
    DEF CYL_CS CylinderSensor {
      minAngle -6
      maxAngle 6
    }
    Shape {
      appearance Appearance {
        material Material {
          diffuseColor 0.2 0.3 0.9
        }
      }
      geometry Cylinder {
        height 1.6
        radius 0.9
      }
    }
  ]
}

DEF SPH_BOX Transform {
  translation 3 -2.5 0
  children [
    DEF SPH_SS SphereSensor { }
    Shape {
      appearance Appearance {
        material Material {
          diffuseColor 0.9 0.8 0.2
        }
      }
      geometry Sphere { }
    }
  ]
}

ROUTE TOUCH_TS.hitPoint_changed TO MARKER.set_translation
ROUTE TOUCH_TS.touchTime TO TOUCH_CLOCK.set_startTime
ROUTE PLANE_PS.translation_changed TO PLANE_BOX.set_translation
ROUTE CYL_CS.rotation_changed TO CYL_BOX.set_rotation
ROUTE SPH_SS.rotation_changed TO SPH_BOX.set_rotation

